import json
from unittest import mock
import openai_client

response = {
    \"output\": [
        {
            \"type\": \"message\",
            \"content\": [{\"type\": \"output_text\", \"text\": \"hello\"}],
        }
    ]
}
with mock.patch.object(openai_client, \"urllib\") as fake:
    fake.request.urlopen.return_value.__enter__.return_value.read.return_value = (
        json.dumps(response).encode()
    )
    result = openai_client.send_text_prompt(\"private prompt\", api_key=\"test-key\")
print(result)
print(openai_client.response_text(result))
